<span class="line"><span style="color:#89DDFF;font-style:italic;">  export</span><span style="color:#C792EA;"> const</span><span style="color:#BABED8;"> version</span><span style="color:#89DDFF;">:</span><span style="color:#FFCB6B;"> string</span></span>
